INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('a5b29548-90c5-40f8-a105-a7def8818dbd', 'euro', 'Euro Game', 'Strategy games emphasizing indirect competition, resource optimization, and elegant mechanical systems over thematic immersion or direct conflict. Players compete primarily through efficiency and timing rather than attacking opponents. Theme is subordinate to mechanism.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('3e6f3897-963d-4c28-a57d-a2bb5bb78a17', 'ameritrash', 'Ameritrash / Thematic', 'Games prioritizing thematic immersion, narrative arc, direct player conflict, and dramatic moments over mechanical elegance. Dice-heavy combat, rich lore, miniatures, and asymmetric player powers are hallmarks. The term is used affectionately within the hobby.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('e55415f0-c598-4c94-876a-9426ec213e1a', 'abstract', 'Abstract Strategy', 'Games with no theme or purely decorative theme, perfect or near-perfect information, no randomness, and victory determined entirely by skill. The purest form of competitive strategy -- two minds in direct contest with no hidden information or luck to blame.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('a37ad51a-41ce-4e29-b082-8ce6c240194e', 'wargame', 'Wargame', 'Games simulating military conflict at tactical, operational, or strategic scales. Typically use hex grids, combat results tables, and detailed order-of-battle information. Prioritize historical accuracy and strategic depth over accessibility.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('696d7aee-94b2-4f26-811a-94061f3e66f9', 'party', 'Party Game', 'Games designed for large groups (6+) with simple rules, short play time, and emphasis on social interaction, humor, and performance over strategic depth. Success depends on creativity, communication, and reading people rather than optimization.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('d718e0c1-2799-4d56-acb9-6d077c504f3d', 'family', 'Family Game', 'Games accessible to mixed-age groups with moderate complexity, satisfying strategic choices, and play times under 60 minutes. The sweet spot between children''s games and hobby games -- deep enough for experienced players, approachable for newcomers.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('60403ebc-2d2b-447d-90d1-1ad56a33ad82', 'cooperative-game', 'Cooperative Game', 'Games where all players work together against the game system to achieve a shared victory condition. If the game wins, everyone loses. Distinguished from semi-cooperative (which includes individual objectives or traitor roles) and from team-based games.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('13019d37-a116-410f-9662-4ff669ff3202', 'solo-game', 'Solo Game', 'Games designed to be played by a single player, either as the primary mode or with a dedicated solo variant. The player competes against the game system, a target score, or their own previous performance.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('8c68ece7-fbf8-4edb-990a-f4a92f5a4311', 'two-player', 'Two-Player Game', 'Games designed specifically for exactly two players (not games that merely "support" two). The design assumes head-to-head competition or cooperation, with mechanics tuned for the two-player dynamic.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('a91fc38c-9613-4cb2-9ddc-2209a312b2cc', 'legacy-game', 'Legacy Game', 'Games where the game state permanently changes across sessions through stickers, destroyed components, sealed boxes, and irreversible decisions. Each play session alters future sessions. The game is consumed through play -- it has a finite lifecycle.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('c733f747-afa8-4c0e-9191-7ab9b28d7f52', 'campaign-game', 'Campaign Game', 'Games with connected sequences of scenarios featuring narrative continuity and mechanical progression. Characters level up, the story branches, and earlier outcomes affect later scenarios. Unlike legacy games, campaigns can typically be reset and replayed.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('da557668-3ac7-4e55-ab64-dc704d86d040', 'dungeon-crawler', 'Dungeon Crawler', 'Games where players explore map tiles, fight monsters, collect loot, and develop characters through tactical grid-based combat. The core loop is explore-fight-loot-upgrade. Distinguished from RPGs by defined scenario structure and board game mechanics.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('34bdc1a6-05a0-4e96-9f12-e744dc887f85', 'real-time-game', 'Real-Time Game', 'Games where all players act simultaneously without turns, racing against a clock or each other. Speed of decision-making and execution matters as much as quality of decisions.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('19421673-4e1f-4e53-9074-bd70190c9699', 'dexterity-game', 'Dexterity Game', 'Games where physical skill -- flicking, stacking, balancing, tossing -- is the primary activity. Strategic thinking is secondary to manual precision and coordination.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('e3490ab9-92ff-4aa1-ad64-182877751788', 'engine-builder', 'Engine-Building Game', 'Games where the core experience is constructing a personal economic engine that produces increasing returns over time. Early turns invest in infrastructure; later turns harvest compound returns.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('6b86330b-c16d-4097-90bf-c9fef7c00c04', 'deck-builder', 'Deck-Building Game', 'Games where constructing a personal deck during play IS the game. The deck is your engine -- acquiring powerful cards and culling weak ones is the central activity, not a supporting mechanism.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('5d79922d-6f86-42a6-8f6c-e5b2575f93b5', 'worker-placement-game', 'Worker-Placement Game', 'Games where assigning workers to action spaces IS the core experience. The blocking and prioritization of limited action spaces defines the game, not just one mechanism among many.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('02754f33-4199-448b-860e-650235e462d4', 'area-control-game', 'Area-Control Game', 'Games where controlling territory IS the central objective and source of tension. Gaining and defending regions on a shared map is the primary activity, not a side mechanism.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('282bd002-b385-4a75-9dda-81b31bbdf97d', 'social-deduction', 'Social Deduction', 'Games where hidden identities and deception are the core experience. Players have secret roles and must deduce who is on which team through conversation, voting, and behavioral analysis.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('5f4021a2-2373-490a-95b4-852962eaa510', 'roll-and-write-game', 'Roll-and-Write Game', 'Games where players roll dice (or flip cards), then mark results on a personal sheet. The format IS the category -- the tactile act of writing on your sheet with shared random input defines the experience.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('f7fe6e2a-3213-48d6-85c5-bedf21bb16e7', 'economic-game', 'Economic Game', 'Games where market dynamics, investment, stock trading, or commodity speculation are the primary systems. Money is not just a resource -- it is the game. Distinguished from euro games by the emphasis on economic simulation over general optimization.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('637b616f-229e-4180-add7-f651029c97dd', 'negotiation-game', 'Negotiation Game', 'Games where deal-making, diplomacy, and interpersonal persuasion ARE the core experience. Mechanical systems exist to create leverage, but the game is won or lost at the negotiation table.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('7281fbad-3134-481e-90c9-5dbbdf2a29cc', 'puzzle-game', 'Puzzle Game', 'Games where solving spatial, logical, or combinatorial challenges is the primary activity. The satisfaction comes from finding optimal solutions to constrained problems.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('c4c3bf9c-8b5d-48e4-9a0b-be65f75ca49a', 'racing-game', 'Racing Game', 'Games where the objective is to reach a destination or achieve a condition first. The competitive pressure of the race -- not point optimization -- is the core tension.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('a3e2d325-9cbf-4af9-ae96-a846b7abb983', 'narrative-game', 'Narrative Game', 'Games where story delivery is a primary design goal. Player choices affect narrative outcomes, and the story experience is as important as the mechanical challenge.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('fb9f4b83-8d02-44b1-b58b-2878a9b1b487', '4x', '4X Game', 'Games structured around four phases: explore, expand, exploit, and exterminate. Typically feature large-scale civilization or space empire building with military, economic, and technological progression systems.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('bc5f97b0-9a39-4f7a-b179-434bfc22810e', 'drafting-game', 'Drafting Game', 'Games where card or tile drafting IS the dominant experience. The strategic evaluation of what to pick and what to pass defines the game more than any other mechanism.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('77d5e810-4e56-4008-ae97-bc5b164a51fe', 'trick-taking-game', 'Trick-Taking Game', 'Games where playing cards into tricks with rank and suit rules IS the game. The trick-taking mechanism is not just present -- it is the entirety of the mechanical experience.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('33801c3c-4b10-41af-adb2-52eda53fd399', 'push-your-luck-game', 'Push-Your-Luck Game', 'Games where the core tension is deciding when to stop pressing your luck. Each successive action or roll increases potential reward but also risk of losing everything accumulated.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('27077ebe-7260-45c0-9b64-025e5700fc79', 'tile-laying-game', 'Tile-Laying Game', 'Games where placing tiles to build a shared or personal geography IS the core activity. The spatial puzzle of tile placement defines the experience more than any other mechanism.', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('c0b9c660-f6db-48f9-9eb5-5d475898b53c', 'print-and-play', 'Print-and-Play', 'Games distributed as digital files for home printing and assembly. A distribution format rather than a design philosophy, but a recognized category with a dedicated community and design conventions (minimal components, standard paper sizes).', NULL);
INSERT INTO public.categories (id, slug, name, description, parent_id) VALUES ('1bea56d1-cfcf-4bca-82ad-a63eee204fc6', 'educational', 'Educational Game', 'Games designed with an explicit learning objective. Teaching content through game mechanics -- history, math, science, language, or other subjects. Distinguished from games that incidentally teach strategy or social skills.', NULL);
INSERT INTO public.games (id, slug, name, sort_name, type, parent_game_id, year_published, description, description_short, min_players, max_players, min_playtime, max_playtime, community_min_playtime, community_max_playtime, community_median_playtime, min_age, community_suggested_age, rating, bayes_rating, rating_votes, rating_stddev, rating_confidence, rating_distribution, weight, weight_votes, top_player_counts, recommended_player_counts, rank_overall, rank_by_category, owner_count, wishlist_count, total_plays, mode, funding_source, language_dependence, image_url, thumbnail_url, bgg_id, status, created_at, updated_at) VALUES ('01923a5b-8c4d-7e6f-9071-a1b2c3d4e5f6', 'terraforming-mars', 'Terraforming Mars', 'terraforming mars', 'base_game', NULL, 2016, 'In Terraforming Mars, players take on the role of corporations working together to terraform the planet Mars by raising the temperature, adding oxygen to the atmosphere, and covering the surface with oceans. Players compete for victory points by contributing to the terraforming process and building infrastructure.', 'Competitive engine-building game where corporations compete to terraform Mars through card-driven resource management.', 1, 5, 120, 120, 90, 210, 150, 12, 14, 8.22, 8.22, 94520, 1.38, 0.68, '{210,380,720,1850,3780,7560,15120,28400,24500,12000}', 3.24, 8940, '{2,3}', '{2,3,4}', 1, NULL, 98200, 4120, 412800, 'competitive', NULL, 'moderate', NULL, NULL, 167791, 'active', '2026-03-17 15:33:23.275941+00', '2026-03-18 00:50:00.154748+00');
INSERT INTO public.games (id, slug, name, sort_name, type, parent_game_id, year_published, description, description_short, min_players, max_players, min_playtime, max_playtime, community_min_playtime, community_max_playtime, community_median_playtime, min_age, community_suggested_age, rating, bayes_rating, rating_votes, rating_stddev, rating_confidence, rating_distribution, weight, weight_votes, top_player_counts, recommended_player_counts, rank_overall, rank_by_category, owner_count, wishlist_count, total_plays, mode, funding_source, language_dependence, image_url, thumbnail_url, bgg_id, status, created_at, updated_at) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'spirit-island', 'Spirit Island', 'spirit island', 'base_game', NULL, 2017, 'In the most distant reaches of the world, magic still exists, and spirits still inhabit the land. Players take on the roles of island spirits working together to drive away colonizing invaders through unique elemental powers and strategic card play. Each spirit has its own strengths, weaknesses, and complexity level.', 'Cooperative strategy game where 1-4 players defend an island from colonizers using unique elemental spirit powers.', 1, 4, 90, 120, 75, 150, 105, 13, 14, 8.30, 8.15, 10, 2.75, 0.03, '{1,0,0,0,0,0,1,1,3,4}', 4.00, 1, '{1,2,3}', '{1,2,3,4}', 2, NULL, 42150, 8420, 187340, 'cooperative', NULL, 'moderate', NULL, NULL, 162886, 'active', '2026-03-17 15:33:23.275941+00', '2026-03-18 00:50:00.154748+00');
