INSERT INTO public.game_categories (game_id, category_id) VALUES ('01923a5b-8c4d-7e6f-9071-a1b2c3d4e5f6', 'e3490ab9-92ff-4aa1-ad64-182877751788');
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('1e7045af-613a-4f48-be7c-c30eb5e7a727', 'dice-rolling', 'Dice Rolling', 'Players roll dice to generate random outcomes that determine actions, movement, combat results, or resource production. The core mechanic is accepting randomized input and making decisions based on or despite the result. Distinguished from push-your-luck by the absence of voluntary stop/continue decisions on the roll itself.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f3223010-3700-4dfe-95c5-457970ed6f23', 'hand-management', 'Hand Management', 'Players hold a private set of cards and must decide which to play, when to play them, and which to retain for future turns. The core tension is opportunity cost -- playing a card now means not having it later. Distinguished from tableau-building by the emphasis on timing and sequencing rather than permanent placement.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('06ee1194-7e7d-4e57-af03-825c316da8b4', 'area-control', 'Area Control', 'Players compete for dominance over defined regions of a shared map. Control is typically determined by having the most units, influence, or presence in a region. Scoring occurs for controlling or having majority in areas. Distinguished from area-movement by the emphasis on relative presence (majority) rather than traversal.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('af7692ba-3df3-4ab8-a9f6-3a998eac1c89', 'set-collection', 'Set Collection', 'Players gather specific combinations of items (cards, tiles, tokens) that score points or grant abilities when completed. The core mechanic is identifying which sets to pursue and competing with opponents for shared resources. Distinguished from pattern-building by the emphasis on accumulation of matching items rather than spatial arrangement.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('81eb0fc3-15cf-4035-9cc8-1b77941a6f2f', 'trading-and-negotiation', 'Trading and Negotiation', 'Players exchange resources, promises, or favors through direct interpersonal communication. Deals may be binding or non-binding. The core mechanic is social -- reading opponents, making offers, and leveraging asymmetric needs. Distinguished from auction by the bilateral (or multilateral) nature rather than competitive bidding.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('cd60a5fc-3317-44fc-a500-3aec50c1838f', 'tile-placement', 'Tile Placement', 'Players place tiles onto a shared or personal play area, creating or extending a spatial structure. Placement decisions consider adjacency, orientation, and how the tile interacts with its neighbors. Distinguished from modular-board by the emphasis on player-driven placement as the core decision rather than setup.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('3c49a51d-7760-4204-a5f0-00deb0f3d96d', 'action-points', 'Action Points', 'Each turn, players receive a fixed budget of action points and choose how to spend them across available actions. Different actions may cost different amounts. The core tension is allocation -- you can do many small things or one big thing. Distinguished from action-selection by the fungible, spendable nature of the points.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f1af3ee6-be59-423c-bafc-82f226777420', 'trick-taking', 'Trick Taking', 'Players play cards from their hand in a series of rounds (tricks). Each trick has a lead suit, and the highest card of the lead suit (or trump suit) wins the trick. The core mechanic is deduction and timing -- tracking what''s been played and managing your hand to win specific tricks. One of the oldest card game mechanics.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('624f3cfd-780d-49aa-a5ef-ecfb79e92ab9', 'action-selection', 'Action Selection', 'Players choose from a shared or personal menu of available actions each turn, with no point budget -- you simply pick one (or a prescribed number). Actions may become unavailable after selection. Distinguished from action-points by the discrete, non-fungible nature of the choices, and from worker-placement by the absence of blocking.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('fdd21d35-00af-4246-b405-1037b2b7e2df', 'worker-placement', 'Worker Placement', 'Players assign a limited pool of worker tokens to action spaces on a shared board. Each space typically accepts only one worker, creating a blocking/exclusivity constraint -- if an opponent takes a space, you cannot use it this round. The core tension is prioritization under scarcity. Distinguished from action-selection by the blocking mechanism and the physical placement of tokens.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('39803ead-6df2-407f-8ce2-bee34362276b', 'worker-placement-different-types', 'Worker Placement with Different Worker Types', 'An evolution of worker placement where workers are not interchangeable -- different workers have different abilities, costs, or access to different action spaces. Adds a layer of strategic consideration to which worker to assign where. Distinguished from basic worker-placement by the asymmetry between worker tokens.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('3caf497b-d410-44eb-afea-7829a9a27ab8', 'dice-placement', 'Dice Placement', 'A variant of worker placement where dice serve as workers. The die value determines which action spaces are available or how effective the placement is. Combines the randomness of dice-rolling with the spatial blocking of worker-placement. Distinguished from basic worker-placement by the random element of die values.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('c4ef57a1-0392-403a-8547-b1462f6f5da8', 'rondel', 'Rondel', 'Players move a marker around a circular track of action spaces. Movement is typically limited (1-3 spaces forward), creating a rhythm where certain actions become available in predictable but constrained patterns. The core tension is tempo -- moving further costs more but reaches better actions. Distinguished from action- selection by the spatial, sequential constraint.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('df94e534-1efd-44a3-b23b-c9ca66cff7f6', 'simultaneous-action-selection', 'Simultaneous Action Selection', 'All players secretly and simultaneously choose their actions, then reveal them at the same time. The core mechanic is prediction -- anticipating what opponents will choose and selecting accordingly. Distinguished from sequential action-selection by the hidden, simultaneous nature of decisions.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('5b714936-bb80-4b8f-9da8-7974839d43b8', 'programmed-movement', 'Programmed Movement', 'Players pre-program a sequence of actions or movements before execution, then all programs resolve in order. The core tension is the gap between planning and execution -- other players'' programs may invalidate your assumptions. Distinguished from simultaneous- action-selection by the sequential, multi-step programming.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('afef689d-8f2a-4eb2-adb1-6bb60aaf7276', 'real-time', 'Real-Time', 'Players act simultaneously without taking turns, racing against a clock or each other. There is no turn structure -- speed of decision-making and execution matters. Distinguished from simultaneous-action-selection by the continuous, unstructured nature of play (no discrete rounds of simultaneous choice).', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('10f1c98f-085e-469f-aa61-0321d14eabce', 'follow', 'Follow / Role Selection', 'One player selects an action or role, and other players may follow (perform a weaker version of that action) or do something else. The selector typically gets a bonus. The core tension is leading vs. following -- do you select the action you want, or follow someone else''s lead for a weaker benefit?', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('fb11a51a-b3ef-401d-b933-83b24c98645a', 'card-drafting', 'Card Drafting', 'Players select cards from a shared pool -- either an open display, a rotating hand of cards (draft), or a market. The core mechanic is evaluation under incomplete information: which card is most valuable to you, and which are you willing to let opponents take? Distinguished from hand-management by the shared selection pool rather than playing from a private hand.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('31f4c78a-0d49-4744-b7e7-bf0bf80ae974', 'deck-building', 'Deck Building', 'Each player starts with an identical small deck and acquires new cards during play that are shuffled into their personal deck. The deck IS your engine -- it improves as you add powerful cards and (critically) remove weak ones. Distinguished from hand-management by the dynamic, evolving composition of your card pool, and from card-drafting by the cycling/reshuffling mechanic.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('c74d7c27-8d15-4486-abfc-66fe8f72e45d', 'bag-building', 'Bag Building', 'A physical variant of deck-building where players draw tokens from a bag rather than cards from a deck. Tokens are added and removed over the course of the game. The bag provides the same evolving-pool mechanic as a deck but with tactile, non-card components. Distinguished from deck-building by the physical medium (bag of tokens vs. shuffled cards).', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('1049eb1b-6291-4134-9f8f-c02b9d5868f7', 'pool-building', 'Pool Building', 'A generalization of deck-building where players build a pool of resources (dice, tokens, cards, or other components) that grows and improves over the game. The pool may not cycle through a discard/reshuffle like a deck -- components may persist in play. Distinguished from deck-building by the broader scope of pooled components and the absence of mandatory cycling.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('389a0917-051a-424e-96ef-03fd75162599', 'tableau-building', 'Tableau Building', 'Players build a personal display (tableau) of cards or tiles in front of them. Cards in the tableau provide ongoing effects, scoring conditions, or production abilities. The tableau represents your engine/infrastructure. Distinguished from hand-management by the permanent, visible nature of placed cards (they stay in play rather than being consumed).', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('0ec02798-77ae-4609-86d5-f617c9cde95a', 'multi-use-cards', 'Multi-Use Cards', 'Cards can be used for multiple distinct purposes -- as an action, for resources, as a map element, for combat value, etc. Players must choose which use to apply, creating opportunity cost on every card. Distinguished from hand-management by the explicit mechanical duality designed into each card.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('2b4f3abc-8a58-474b-a08a-38efc6b01278', 'melding', 'Melding and Splaying', 'Players form groups of cards (melds) by matching suits, values, or other attributes, and lay them on the table. Splaying refers to fanning cards to reveal icons on partially hidden cards. A traditional card game mechanic adapted into modern designs.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('5a915059-5426-4854-9c64-37e42f229547', 'ladder-climbing', 'Ladder Climbing', 'Players play cards or combinations that must beat the previous play in value or rank. Play continues until all players pass, then the last player to play leads the next round. The "ladder" is the escalating minimum. Distinguished from trick-taking by the variable-length rounds and the emphasis on shedding cards rather than winning individual tricks.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('bf1fa0d2-58d2-42b0-85e8-16bbed69c239', 'resource-management', 'Resource Management', 'Players collect, store, convert, and spend various resources to take actions and score points. The core tension is allocation -- which resources to acquire, when to convert, and when to spend. This is a broad, foundational mechanic present in most strategy games. Distinguished from engine-building by the emphasis on allocation rather than production optimization.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('232c502d-f553-45b4-9681-fb6e5d472936', 'engine-building', 'Engine Building', 'Players construct a personal system (the "engine") of interlocking components that produces increasingly powerful outputs over time. Early turns invest in infrastructure; later turns harvest the compound returns. The core satisfaction is watching your engine accelerate. Distinguished from resource-management by the emphasis on constructing a production system rather than managing individual resources.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('2c11e0c3-99a0-49b3-bb1d-97b0213e53fc', 'auction', 'Auction / Bidding', 'Players compete for items, rights, or privileges by placing bids. The highest bidder wins the item and pays their bid (or a variant). Auction formats include English (ascending), Dutch (descending), sealed-bid, and once-around. The core mechanic is valuation -- how much is this item worth to you vs. your opponents?', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('0f6ff147-86dd-47d6-bed8-9f522be3dabd', 'market', 'Market', 'A shared economic mechanism where goods have prices that fluctuate based on supply, demand, or other game-state factors. Players buy and sell at market prices. Distinguished from auction by the impersonal, systemic nature of pricing (the market sets prices, not competing bids).', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('6b3ebe29-6ff9-4712-a012-1ce8011f2cd8', 'stock-holding', 'Stock Holding', 'Players buy and sell shares or stakes in companies, factions, or entities whose value fluctuates during the game. Dividends, mergers, and market manipulation are common. The core mechanic is speculation and investment. Distinguished from market by the focus on ownership stakes rather than commodity trading.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('3c8ac346-c7ba-44bf-aae3-2be078809926', 'pick-up-and-deliver', 'Pick-Up and Deliver', 'Players transport goods, passengers, or resources from one location to another on the game board to fulfill contracts or score points. The core mechanic is route optimization -- planning efficient paths that pick up at source and deliver to destination. Distinguished from network-building by the emphasis on traversal rather than construction.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('6103e511-50d9-4629-bb5d-c80fe17ae0ba', 'contracts', 'Contracts', 'Players claim objective cards (contracts) that specify required deliverables (sets of resources, routes completed, etc.) and provide rewards upon fulfillment. The core tension is selecting contracts you can efficiently complete while blocking opponents from easy ones.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('4ba28bf4-d452-406c-bfe7-26b49673ebb6', 'tech-tree', 'Tech Tree / Tech Track', 'Players advance along branching or linear tracks that unlock new abilities, units, or actions. Earlier technologies often prerequisite later ones. The core mechanic is long-term strategic planning -- choosing a development path and committing to it. Distinguished from engine-building by the structured, often shared progression path.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('8c12b32f-09bb-45d8-967a-340f72a78e3e', 'area-movement', 'Area Movement', 'Players move units between defined regions (areas) on a map. Areas are connected by adjacency, and movement typically costs actions or movement points. Distinguished from point-to-point by the region-based (rather than node-based) map structure, and from grid-movement by the irregular, non-uniform area shapes.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('507f8bc3-5993-4a2b-b430-221e536c9fd8', 'network-building', 'Network and Route Building', 'Players construct connections (routes, tracks, pipes) between nodes on a map. The network grows over time and typically provides scoring for connectivity, length, or coverage. The core mechanic is spatial planning and blocking. Distinguished from area-movement by the emphasis on construction of infrastructure rather than traversal.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('1d019b39-7c21-433d-a411-c7060dc57ac8', 'hidden-movement', 'Hidden Movement', 'One or more players move secretly on the map, recording their position privately while other players try to deduce their location. Creates asymmetric information and cat-and-mouse tension. Distinguished from hidden-roles by the spatial, movement-based nature of the hidden information.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('132f53da-8272-459a-8705-2aa42b2fe9c3', 'grid-movement', 'Grid Movement', 'Players move units on a grid of squares or hexagons. Movement is measured in spaces. Grid provides uniform, calculable distances and clear adjacency. Distinguished from area-movement by the regular, uniform spatial structure.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('e9bf2bf9-f305-452a-9903-6d345fefc3c3', 'modular-board', 'Modular Board', 'The game board is assembled from interchangeable pieces at the start of (or during) the game, creating a different map each session. Increases replayability through spatial variability. Distinguished from tile-placement by the setup/configuration role rather than in-game placement decisions.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('b3361ddb-eca4-48fd-a72c-6c83f821d0fd', 'enclosure', 'Enclosure', 'Players surround or enclose areas on the board to claim them. The enclosed region is scored or controlled. Combines spatial reasoning with area-control concepts. Distinguished from area-control by the requirement to physically surround an area rather than merely having majority presence.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('be48e69d-f62b-48ca-a469-115213a8d0de', 'cooperative', 'Cooperative Play', 'All players work together against the game system to achieve a shared victory condition. If the game wins, all players lose. The core mechanic is collaborative decision-making under pressure. Distinguished from semi-cooperative by the absence of individual win conditions or traitor roles.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f36154fb-4a8e-44ea-9c4f-69d608d907e0', 'semi-cooperative', 'Semi-Cooperative', 'Players work together toward a shared goal but also compete for individual standing. The group can lose collectively, but among survivors, there is a winner. May include a traitor. Distinguished from full cooperative by the competitive individual layer.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('12a29aa2-0023-4e25-953a-e769af3dedb1', 'traitor', 'Traitor Mechanic', 'One or more players are secretly working against the group while pretending to cooperate. The traitor(s) win by sabotaging the group''s objective without being detected. Combines cooperative play with hidden-roles and social deduction.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('15d04442-c63b-4fa3-b554-46c08d04b45a', 'hidden-roles', 'Hidden Roles / Social Deduction', 'Each player is secretly assigned a role or team allegiance at the start of the game. Players must deduce who is on which team through behavior, voting patterns, and communication. The core mechanic is reading people. Distinguished from hidden-movement by the social/behavioral nature of the hidden information rather than spatial.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f91ae80a-e1da-4e10-9f69-8854dc55a466', 'bluffing', 'Bluffing', 'Players make claims or take actions that may be truthful or deceptive, and opponents must decide whether to believe or challenge them. The core mechanic is credibility management -- establishing a pattern of truth to make lies believable. Distinguished from hidden-roles by the active, voluntary nature of deception rather than assigned secret identities.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('d50b8fd8-d958-4454-b0c5-21ce591cad1e', 'deduction', 'Deduction', 'Players use logic, elimination, and evidence to determine hidden information (a culprit, location, code, etc.). The core mechanic is structured reasoning from partial information. Distinguished from social-deduction/hidden-roles by the logical (rather than behavioral) nature of the deduction.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('355c2cf9-37f1-42f0-8390-394f10c7e2a4', 'communication-limits', 'Communication Limits', 'Players in a cooperative game face restrictions on what information they can share with teammates. May not show cards, may not discuss specific values, or may only communicate through structured mechanisms. Creates tension between cooperation and information asymmetry.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f3e019ef-d3f3-4e02-a60c-2ee9f425bdd3', 'voting', 'Voting', 'Players collectively decide outcomes through a voting mechanism. Votes may be public or secret, equal or weighted. The core mechanic is political -- building coalitions, persuading others, and timing proposals. Distinguished from negotiation by the formal, structured decision mechanism.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('0a729fef-fb8f-4af3-ae29-a0c6cbae14c5', 'push-your-luck', 'Push Your Luck', 'Players repeatedly choose between banking current gains or risking them for greater rewards, with escalating probability of total loss. The core tension is greed vs. prudence. Distinguished from dice-rolling by the voluntary stop/continue decision after each roll or draw.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('1f88a889-6c89-4fbf-ae49-2426aa5bbc1b', 'roll-and-write', 'Roll and Write', 'Players roll dice (or flip cards) and all players simultaneously record/mark results on personal score sheets. The core mechanic is optimization -- using shared random input to make locally optimal marking decisions. Evolved from dice-rolling by adding permanent recording. "Flip and write" is a card-based variant.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('78778275-ac15-4002-9602-f548264b60f0', 're-rolling-and-locking', 'Re-Rolling and Locking', 'After an initial dice roll, players may choose to re-roll some dice while locking others in place. Multiple re-rolls may be allowed. The core mechanic is selective risk -- which dice to keep and which to gamble on improving. Distinguished from push-your-luck by the granular, per-die decision rather than all-or-nothing.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f83b0269-a49a-4222-978f-d1bd9e7e7f09', 'pattern-building', 'Pattern Building', 'Players arrange components into specific spatial patterns to score points. The pattern requirements may be prescribed (objective cards) or emergent (adjacency bonuses). Distinguished from set-collection by the spatial arrangement requirement -- it''s not just WHAT you collect but WHERE you place it.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('490eb5a9-690f-4d94-b4a4-f725fabe6194', 'end-game-bonuses', 'End Game Bonuses', 'Players score additional points at game end based on specific conditions they''ve met (set bonuses, area majorities, personal objectives). Often hidden or variable. The core mechanic is long-term planning toward scoring conditions that aren''t immediately visible in the point total.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('92d32889-8267-41ba-a629-75e334bd6dae', 'variable-player-powers', 'Variable Player Powers', 'Each player has unique abilities, starting resources, or rules that differ from other players. Asymmetry creates different strategic paths and forces players to adapt to their specific powers. Distinguished from hidden-roles by the public, known nature of the asymmetry.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('6a03b582-3c25-4240-91e9-85f110d75c12', 'take-that', 'Take That', 'Players directly attack, hinder, or steal from specific opponents through targeted aggressive actions. The core mechanic is direct conflict aimed at a chosen player. Distinguished from area-control (indirect competition for space) by the deliberate, personal targeting of an opponent.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('0b56de72-0110-45fa-8fe1-ff34ae68a4c3', 'solo', 'Solo / Solitaire Mode', 'A game mode designed for a single player, either as the primary mode or as a variant of a multiplayer game. The player competes against an automated opponent (automa), a scoring threshold, or the game system itself. Distinguished from cooperative by the single-player nature.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('e67e7ab8-dfef-4b4c-a947-39c80dfe744f', 'dexterity', 'Dexterity', 'Players use physical skill (flicking, stacking, balancing, tossing) to determine outcomes. The core mechanic is manual precision rather than strategic decision-making. Distinguished from all other mechanic families by the physical skill component.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('a6ddc9fc-1548-4fd8-a977-f09235f985fc', 'flicking', 'Flicking', 'Players flick discs or tokens with their fingers to move them across a playing surface. Accuracy and force control determine outcomes. A specific type of dexterity mechanic.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('3d63679a-f7c0-4dd0-826b-87158c9ed8fe', 'legacy', 'Legacy', 'The game permanently changes between sessions -- components are destroyed, stickers are applied, new rules are revealed, and decisions carry forward irreversibly. Each campaign is unique and unrepeatable. Distinguished from campaign by the permanent, physical modification of game components.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('4d3f8c04-3328-427a-9b8d-929365170420', 'campaign', 'Campaign / Scenario', 'A series of connected games (scenarios) played in sequence, with narrative continuity and mechanical progression between sessions. Characters may level up, the story branches, and earlier outcomes affect later scenarios. Distinguished from legacy by the non-destructive nature -- the game can typically be reset and replayed.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('55167009-46a2-44f9-9c46-d2e5f26707bb', 'narrative-choice', 'Narrative Choice', 'Players make story-driven decisions that branch the narrative in different directions. Choices affect which content is encountered, how the story unfolds, and often the game''s outcome. The core mechanic is storytelling through player agency. Distinguished from campaign by the emphasis on branching narrative rather than mechanical progression.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('2a5a7036-58b3-4552-8eae-fd68c761d5ff', 'i-cut-you-choose', 'I Cut, You Choose', 'One player divides a resource (cards, territory, points) into portions, and another player chooses which portion to take. The divider is incentivized to make fair divisions because the chooser picks first. An elegant fairness mechanism.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('046ad5eb-b47e-4b55-8359-c4315aed9a5c', 'player-elimination', 'Player Elimination', 'Players can be permanently removed from the game before it ends. Eliminated players sit out while others continue. Generally considered a negative mechanic in modern design because eliminated players have nothing to do. Included for completeness and historical context.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('fe3cc25a-412a-4c33-b2b0-1829a69142e9', 'income', 'Income / Automatic Resource Growth', 'Players receive resources automatically at regular intervals (start of turn, start of round) based on their current position, infrastructure, or game state. The amount typically grows as players develop their engine. Distinguished from resource-management by the automatic, passive nature of the acquisition.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('2d8f1a9d-85ff-4acd-91b8-fe008b929ef8', 'once-per-game-abilities', 'Once-Per-Game Abilities', 'Players have powerful abilities that can only be used once during the entire game. The core tension is timing -- using it too early wastes its potential, but waiting too long risks never using it. Creates memorable, dramatic moments.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('225e271d-4897-48c3-9174-01b6d7bc6cc2', 'auction-english', 'English Auction', 'An ascending-bid auction where players take turns raising the bid. The last bidder standing wins the item at their bid price. Creates escalating tension as players decide when to drop out. The most intuitive auction format, familiar from real-world auctions.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('fe39fa5e-c65b-4776-8547-e591691b9150', 'auction-dutch', 'Dutch Auction', 'A descending-price auction where the price starts high and drops until a player claims the item. The tension is reversed from English auctions -- wait longer for a better price, but risk someone else grabbing it first. Named after Dutch flower auctions.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('094e7b7f-6da4-4b8c-862b-05b0bc9305e9', 'auction-sealed-bid', 'Sealed Bid', 'All players simultaneously and secretly submit a single bid, then reveal. Highest bid wins. Eliminates the iterative back-and-forth of open auctions and forces players to evaluate in isolation. Creates bluffing opportunities since you cannot react to others'' bids.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('6e12ec1a-c4e8-49d1-997a-4d04be7ef05a', 'auction-once-around', 'Once Around Auction', 'Each player gets exactly one opportunity to bid (or pass) in turn order. No second chances -- you bid once and live with it. Faster than English auctions and creates sharp decisions about bid sizing.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('56ca0376-454d-4eee-bbea-70fa508e7266', 'turn-order-auction', 'Turn Order Auction', 'Players bid specifically for position in the turn order. Earlier positions provide strategic advantage (first pick, first placement) but cost more. Creates an explicit market for initiative. Common in economic games where turn order significantly impacts outcomes.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('ae23e7dd-e79e-4df9-8fc1-aa64cc3639c0', 'point-to-point-movement', 'Point-to-Point Movement', 'Players move between discrete locations (nodes) connected by defined routes or paths. Unlike area movement where regions are adjacent zones, point-to-point uses an explicit graph of connections. Movement is typically along specific routes with defined costs.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('b64478d6-df80-4ab5-a900-29a92a28784e', 'crayon-rails', 'Crayon Rails', 'Players physically draw routes on the game board using crayons or markers, creating permanent (for that game) connections between cities. Uniquely tactile -- your network is literally drawn by hand. Typically combined with pick-up-and-deliver economics.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('50e7106b-239b-44b5-a890-35cba2ba834e', 'measurement-movement', 'Measurement Movement', 'Players measure movement distance using a physical ruler, tape measure, or range tool rather than counting spaces on a grid. Dominant in miniature wargaming. Adds spatial precision but also physical skill in positioning and measuring.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('ceeec24f-c8c9-4445-95d4-4e0df5f32dc0', 'mancala', 'Mancala / Sowing', 'Players pick up all pieces from a pit or space and distribute them one at a time into consecutive spaces in a defined direction (sowing). The mechanic creates cascading, hard-to-predict outcomes as the distribution pattern depends on current board state. One of the oldest known game mechanics.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('edafe01a-3053-4b65-9a75-390e8479da0c', 'map-exploration', 'Map Exploration', 'The play area is not fully revealed at game start. Players discover new map tiles, cards, or areas during play through exploration actions. Creates genuine discovery and replayability since the map differs each game. Distinguished from modular-board by the progressive, mid-game revelation.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('4e0925c3-dd27-4e3b-8f7f-cf50f1e2acb0', 'track-movement', 'Track Movement', 'Players move tokens along a single linear or looping track. Movement is typically determined by dice or card play. The track may represent a race course, score track, or progression path. Simple and intuitive -- the most basic form of spatial movement.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('9224c251-1ec9-4b77-b9c2-d47620b3fa62', 'open-drafting', 'Open Drafting', 'Players select cards (or tiles) from a face-up, visible market or display. Everyone can see what is available and what opponents take. Distinguished from closed-drafting by the full visibility of options and from general card-drafting by the specific market/display mechanism.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('fed34d5e-8840-4bdd-8a90-5f3f8b5151e3', 'closed-drafting', 'Closed Drafting', 'Each player receives a hand of cards, selects one to keep, then passes the remaining cards to an adjacent player. This pass-and-pick continues until all cards are drafted. Creates tension between taking what you want and denying opponents what they need.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('fb0e1861-e922-4794-b323-38b62af92fd0', 'card-driven', 'Card-Driven Game', 'Cards serve as the primary action mechanism, typically representing historical events with specific effects AND generic operational value. Players face a constant dilemma: use a card for its event text or for its operational points. Revolutionized wargame and political simulation design.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('2c0b9a3b-a491-492c-a9ca-a88a1f7d0eaf', 'command-cards', 'Command Cards', 'Cards dictate which units or sections of the board a player may activate on their turn. Creates fog of war and force limitations -- you may want to attack the left flank but lack the cards to order those units. Evolved from card-driven games into a simpler, more tactical format.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('38486d35-4265-4271-a1e0-d0609219e6ae', 'deck-construction', 'Deck Construction', 'Players build a custom deck BEFORE the game begins, selecting cards from a larger pool according to construction rules (deck size, card limits, faction restrictions). The pre-game construction IS a core strategic layer. Distinguished from deck-building which constructs the deck DURING play.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('edcae7ce-67b7-41a4-bd99-493fba5e8199', 'dice-combat', 'Dice-Based Combat', 'Conflicts between players are resolved by rolling dice, with results determining hits, casualties, or outcomes. May involve modifiers from terrain, unit types, or technology. The randomness creates dramatic swings but can be mitigated by numbers advantage or positioning.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f29880c2-06ef-46d3-a40c-e2e69a7c7bf8', 'card-combat', 'Card-Based Combat', 'Conflicts are resolved through card play rather than dice. Players simultaneously or sequentially play cards from hand to determine combat strength, special abilities, or combat modifiers. Replaces randomness with hand management and bluffing.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('0e881a16-a42e-428d-a421-c3d6de1215d4', 'combat-results-table', 'Combat Results Table', 'Combat outcomes are determined by cross-referencing attacker/defender strength ratios with a die roll on a standardized table. The CRT produces results like "Defender Eliminated," "Exchange," or "Attacker Retreat." Foundational to hex-and-counter wargaming.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('4c230008-c4e2-4d65-93cb-ae979cf7f62f', 'tug-of-war', 'Tug of War', 'A shared marker or track moves bidirectionally between opposing goals. One player''s progress is the other''s retreat. Creates a zero-sum tension where every action both advances your position and pushes back your opponent. Common in two-player conflict games.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('839514d6-33fe-49dc-b7e2-d94bc902ef23', 'alliances', 'Alliances', 'Players can form temporary or formal partnerships within a competitive game. Allied players cooperate against common threats while knowing the alliance will eventually dissolve. Creates a layer of diplomacy, trust, and betrayal above the base mechanics. Distinguished from cooperative by being optional and temporary.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('3dea3d98-7444-4f11-b129-19e0310320c5', 'storytelling', 'Storytelling', 'Players collaboratively or competitively create narratives during play. The story IS the game -- players contribute story elements, guide plot direction, or judge narrative quality. Distinguished from narrative-choice by the open-ended creative generation rather than selecting from predetermined options.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('627566d6-0dcd-450a-acde-0056c77e3086', 'acting-performance', 'Acting / Performance', 'Players physically act out, mime, describe, or draw concepts for teammates to guess. The core skill is communication under constraint (no certain words, no talking, only gestures). Party game staple that relies on social and creative skills rather than strategic thinking.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('b5c09d8c-336f-4345-9c6b-4601480c31a7', 'commodity-speculation', 'Commodity Speculation', 'Players buy and sell commodities whose prices fluctuate based on supply, demand, and market events. Profit comes from buying low and selling high, or cornering a market. Distinguished from stock-holding by trading fungible goods rather than ownership stakes.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('d6517120-defc-4595-9dfc-99b5b353e76c', 'closed-economy', 'Closed Economy', 'The total money supply in the game is fixed -- money paid by players goes to other players or the bank, and money received comes from the same pool. No new money is created. Creates scarcity tension and makes every transaction a true resource transfer.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('6cc9e27e-5bbe-4576-b6e6-5da1ff304c2f', 'loans', 'Loans', 'Players can borrow money or resources from the game system, gaining immediate liquidity at the cost of future repayment with interest or penalties. Creates tension between short-term investment and long-term debt burden. Distinguished from income by the explicit debt obligation.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('9b1e1eda-3f1d-4fc3-a7c5-e4319fa8c815', 'resource-conversion', 'Resource Conversion', 'Players transform one type of resource into another through defined conversion actions or recipes. The conversion chain -- turning raw materials into refined goods into victory points -- forms the core strategic puzzle. Distinguished from trading by converting through game actions rather than player negotiation.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('4eb79272-673b-478e-a1a9-8d874cc7fd88', 'investment', 'Investment', 'Players commit resources to ventures with uncertain or delayed returns. The payoff depends on future game state, other players'' actions, or random events. Creates risk-reward decisions distinct from direct resource spending. Distinguished from loans by the uncertain return rather than guaranteed debt.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('8770af68-b2ee-480f-bf50-3f95b3fd880c', 'variable-phase-order', 'Variable Phase Order', 'Players choose which phase or role will be active each round. All players may participate in the chosen phase, but the chooser gets a bonus. Gives the selecting player partial control over game tempo and creates interaction through phase selection. Pioneered by Puerto Rico''s role selection mechanism.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('81f4a305-8b17-4ea2-91a1-04bd2398e936', 'chaining-combos', 'Chaining / Combos', 'Playing one card or taking one action triggers a cascade of additional effects, each potentially triggering further effects. Building an engine that produces long combo chains is the core satisfaction. Distinguished from engine-building by the focus on the chain execution itself rather than the construction of the production system.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('088b8255-035d-40e7-a85d-09903efad2c3', 'action-retrieval', 'Action Retrieval', 'Players must spend actions or turns to recover their previously placed workers, tokens, or action markers before they can be redeployed. Creates a tempo cost -- you cannot keep placing indefinitely without pausing to retrieve. Adds a planning dimension to worker placement.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('ac14b9b5-9b63-413a-bea9-d77a4b136ee7', 'chit-pull', 'Chit-Pull Activation', 'Chits (tokens) representing units, factions, or actions are drawn randomly from a container to determine activation order. Creates uncertainty about when (or whether) your forces will activate. Simulates fog of war and command friction. Dominant in wargaming but appearing in modern designs.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('03b1120d-efc7-4ace-ada0-e6e424e26620', 'force-commitment', 'Force Commitment', 'Players must commit forces, resources, or actions to conflicts or areas before the outcome or opponent''s commitment is revealed. Simultaneous commitment creates bluffing, over/under-commitment dilemmas, and risk of wasted resources on uncontested areas.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('c3a1b5fa-ab3e-40c0-a586-db6497335dff', 'race-to-finish', 'Race', 'The game ends immediately when a player achieves a specific condition -- reaching a point threshold, completing objectives, or crossing a finish line. There is no fixed round count. Creates urgency and allows players to control game length through their strategic choices.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('41b9ac0a-2fe5-4e2a-aa75-6db6a4770b5e', 'catch-up', 'Catch-Up Mechanism', 'Game systems that help trailing players close the gap with leaders. May include targeted attacks on the leader, bonuses for losing players, or diminishing returns for leading. Prevents runaway leaders and maintains competitive tension throughout. Can be explicit (rubber-banding) or emergent (target the leader).', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('ebef9d3d-c584-4913-af9e-f2dc72d7a368', 'scoring-rounds', 'Scoring Rounds', 'The game includes periodic scoring phases at predetermined intervals (every few rounds, at the end of epochs/ages). Players earn points based on their current board state during each scoring round. Creates strategic tension around preparing for upcoming scoring versus long-term investment.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f6a19af5-a790-453e-93e8-d328ec8c9626', 'end-game-trigger', 'End-Game Trigger', 'The game ends not after a fixed number of rounds but when a player or game condition triggers the endgame -- depleting a supply, reaching a threshold, or filling a board. The triggering player often has strategic advantage from timing the ending. Creates tension between triggering early (with a lead) or extending the game (to catch up).', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('862702aa-7997-49ab-9341-ccfdd4f474c3', 'hex-and-counter', 'Hex-and-Counter', 'A wargaming system using a hexagonal grid overlaid on a map with cardboard counters representing military units. Hex grids provide uniform movement distances in all six directions (unlike square grids). Counters encode unit type, strength, and movement via printed values. The foundational wargame format.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('87a77773-fc20-453c-b8d7-eb1422fc75d4', 'fog-of-war', 'Fog of War', 'Information about opponent positions, unit strengths, or board state is hidden from players. May use face-down counters, hidden deployment, or separate maps. Simulates the uncertainty of real military intelligence. Distinguished from hidden-movement by the broader scope -- not just position but also composition and strength.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('10ab4a73-4310-4cfd-90b6-8d499850ca89', 'supply-lines', 'Supply Lines', 'Units require a chain of supply connecting them back to a supply source. Units cut off from supply suffer penalties (reduced combat strength, attrition, inability to attack). Forces players to consider logistics alongside tactics -- overextension is punished.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('e71fbdbf-ea36-4d2f-a54b-cf4654885edc', 'line-of-sight', 'Line of Sight', 'Attacking or interacting with a target requires a clear line of sight from the acting unit. Terrain features, walls, and other obstacles can block LOS. Adds a spatial/geometric puzzle layer to tactical combat. Players must consider positioning and cover.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('de649e92-80bb-4e86-bea4-2723c46d2046', 'variable-setup', 'Variable Setup', 'The initial game state is randomized or configured differently each play. Board layout, starting resources, available cards, or goal conditions change between games. Increases replayability by preventing solved openings. Distinguished from modular-board by applying to all game components, not just the map.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f40bda6f-7202-419d-820c-ad7031415e46', 'stacking', 'Stacking / Balancing', 'Players physically stack game components (blocks, cards, meeples) on top of each other, requiring manual dexterity and spatial judgment. Knocking over the stack typically incurs penalties. Creates tension that scales with stack height.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('4f2b97b5-46cb-4994-8f82-5b45dabdba62', 'map-addition', 'Map Addition', 'New areas, tiles, or board sections are added to the play area during the game, expanding the available geography. Unlike map exploration (which reveals pre-placed hidden tiles), map addition creates genuinely new playable space. The game world literally grows during play.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('007e97b7-3ae3-489b-954c-3195a59acf40', 'speed-matching', 'Speed Matching', 'Players race to identify matching symbols, patterns, or connections faster than opponents. Combines pattern recognition with reaction speed. No turn structure -- the fastest player wins each contest. Pure reflex and visual processing.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('5c2d20a7-8c57-407a-b825-c72b4282d569', 'memory', 'Memory', 'Players must remember the locations, identities, or attributes of hidden game elements (typically face-down cards or tiles). Success depends on recall ability. The mechanic tests cognitive function rather than strategic reasoning. Often combined with matching.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('8ce7bcba-cc18-43c7-baea-533e26d3dfe8', 'worker-placement-with-bumping', 'Worker Placement with Bumping', 'A variation of worker placement where occupied spaces CAN be used by placing a higher-value worker or paying a cost. The displaced worker returns to its owner (possibly with compensation). Reduces the pure blocking of traditional worker placement while maintaining spatial competition.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('ec16b9ec-6164-4d25-819a-d6296f4b920d', 'king-of-the-hill', 'King of the Hill', 'A specific location, objective, or status grants significant ongoing benefits to whoever controls it. Other players continually contest this position, creating a focal point of conflict. The position is powerful but precarious -- everyone targets you.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('08662027-915c-4a9b-b20d-13440081a005', 'elapsed-real-time', 'Elapsed Real Time', 'A physical timer or clock constrains play. Players must complete actions within a time limit, or the game state advances with penalties. Distinguished from real-time by using time as a resource or constraint rather than eliminating turns entirely. The clock creates urgency within a turn-based structure.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('8365f139-6483-4c55-991f-94fdd035f420', 'move-through-deck', 'Move Through Deck', 'Players advance through a deck of cards that serves as the game''s map, encounter system, or progression track. Each card drawn represents a new location, event, or challenge. The deck IS the game space -- exploration and deck depletion are intertwined.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('0be5c35c-2233-4ac8-824e-dc0c546e8424', 'score-and-reset', 'Score and Reset', 'The game consists of multiple rounds or hands. After each round, players score based on that round''s outcome, then the game state resets for the next round. Total score across all rounds determines the winner. Common in card games and trick-taking.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('bf8a4183-dd93-4455-a626-1bf31db645c2', 'sudden-death-ending', 'Sudden Death Ending', 'The game can end abruptly and immediately when a specific condition is met, regardless of round structure. Checkmate in chess, destruction of a key unit, or a critical failure can instantly end the game. Creates constant threat awareness and prevents complacency.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('2df2d5eb-48a3-40d6-97c8-d76136e0e124', 'increase-value-unchosen', 'Increase Value of Unchosen Resources', 'Resources, cards, or options that are not selected by any player accumulate bonus value (coins, tokens, appeal) over time. Creates a self-balancing market -- unpopular options become increasingly attractive. Prevents any option from being permanently worthless.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('f581605f-516b-407b-944b-2a80b7d41d1e', 'events', 'Events', 'Cards or other game elements trigger predetermined events that alter the game state, introduce new conditions, or create crises that all players must respond to. Events inject narrative and unpredictability, often simulating external forces acting on the game world.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('22ff30e9-81d6-4f95-8b15-a50c2862bc98', 'paper-and-pencil', 'Paper and Pencil', 'Players write, draw, or record on paper as a core game mechanic. May involve writing answers, drawing pictures, filling in grids, or recording routes. The ancestor of modern roll-and-write games. Requires minimal components -- just writing implements and paper.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('be3a4579-68fe-4773-ad43-9f536eb704ca', 'order-counters', 'Order Counters', 'Players secretly and simultaneously assign order tokens to their units, regions, or action spaces. All orders are then revealed and resolved. Creates a programming-like experience for military command -- you commit plans before seeing opponent actions. Distinguished from programmed-movement by the focus on unit orders rather than movement sequences.', NULL);
INSERT INTO public.mechanics (id, slug, name, description, parent_id) VALUES ('d81c1b1a-0496-4b70-b5c7-abb6ea271537', 'bribery', 'Bribery', 'Players offer resources, favors, or promises to other players in exchange for specific actions, votes, or support. Distinguished from standard trading by the power asymmetry -- one player pays another to act in their interest rather than exchanging mutual value. Corruption as a game mechanic.', NULL);
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'f3223010-3700-4dfe-95c5-457970ed6f23');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'be48e69d-f62b-48ca-a469-115213a8d0de');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', '92d32889-8267-41ba-a629-75e334bd6dae');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', '3c49a51d-7760-4204-a5f0-00deb0f3d96d');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', '06ee1194-7e7d-4e57-af03-825c316da8b4');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'e9bf2bf9-f305-452a-9903-6d345fefc3c3');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01923a5b-8c4d-7e6f-9071-a1b2c3d4e5f6', 'f3223010-3700-4dfe-95c5-457970ed6f23');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01923a5b-8c4d-7e6f-9071-a1b2c3d4e5f6', '232c502d-f553-45b4-9681-fb6e5d472936');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01923a5b-8c4d-7e6f-9071-a1b2c3d4e5f6', 'cd60a5fc-3317-44fc-a500-3aec50c1838f');
INSERT INTO public.game_mechanics (game_id, mechanic_id) VALUES ('01923a5b-8c4d-7e6f-9071-a1b2c3d4e5f6', '92d32889-8267-41ba-a629-75e334bd6dae');
INSERT INTO public.game_relationships (source_game_id, target_game_id, relationship_type, ordinal) VALUES ('01912f4c-8a2b-7c3d-9e4f-0a1b2c3d4e5f', '01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'expands', 0);
INSERT INTO public.game_relationships (source_game_id, target_game_id, relationship_type, ordinal) VALUES ('01912f4c-9b3c-7d4e-af50-1b2c3d4e5f60', '01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'expands', 0);
INSERT INTO public.game_relationships (source_game_id, target_game_id, relationship_type, ordinal) VALUES ('01912f4c-ac4d-7e5f-b061-2c3d4e5f6071', '01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'expands', 0);
INSERT INTO public.game_relationships (source_game_id, target_game_id, relationship_type, ordinal) VALUES ('01912f4c-bd5e-7f60-c172-3d4e5f607182', '01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'integrates_with', 0);
INSERT INTO public.game_relationships (source_game_id, target_game_id, relationship_type, ordinal) VALUES ('01912f4c-ce6f-7071-d283-4e5f60718293', '01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'expands', 0);
INSERT INTO public.game_relationships (source_game_id, target_game_id, relationship_type, ordinal) VALUES ('01912f4c-df70-7182-e394-5f6071829304', '01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'expands', 0);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('b22b0236-7918-4db3-af35-baa91d965359', 'fantasy', 'Fantasy', 'Games set in worlds with magic, mythical creatures, or supernatural elements. Includes high fantasy (epic quests, wizards), dark fantasy (grimdark), and fairy-tale settings. The setting is non-historical and features elements that violate real-world physics.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('551bb5ed-70bb-4553-92f0-caa1b30cc387', 'fairy-tale', 'Fairy Tale / Storybook', 'Games with whimsical, folk-tale, or storybook settings. Lighter tone than general fantasy -- fairy godmothers, enchanted forests, talking animals. Often family-friendly.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('f5e8f8b3-62c1-44df-8f11-871119daede8', 'science-fiction', 'Science Fiction', 'Games set in futures with advanced technology, space travel, alien civilizations, cyberpunk dystopias, or speculative science. The setting assumes technological progress beyond the present day.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('15be40ba-d40b-4966-a765-b1c1cce72def', 'space', 'Space / Interstellar', 'Games specifically set in outer space -- interstellar travel, space exploration, galactic empires, asteroid mining. The void of space and interplanetary scale are central to the setting.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('c9598dcf-c61f-4b72-b8be-4aedfa9619d0', 'cyberpunk', 'Cyberpunk', 'Games set in near-future dystopias featuring megacorporations, hacking, cybernetic augmentation, and the intersection of high technology with social decay.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('3d5622e0-12c3-4d24-8b01-6579f38fbd50', 'post-apocalyptic', 'Post-Apocalyptic', 'Games set after societal collapse -- nuclear war, plague, environmental disaster, or other cataclysm. Survival, scavenging, and rebuilding in a ruined world.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('3627e5c6-29dd-4d64-b6d9-309b1bd9ea93', 'historical', 'Historical', 'Games based on real historical events, periods, or figures. The setting draws from documented history and often aims for some degree of historical accuracy in its scenario or mechanics.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('90ef422e-e4cd-488f-9253-04cf58197bd5', 'medieval', 'Medieval', 'Games set in the European Middle Ages (~500-1500 CE). Knights, castles, feudalism, crusades, and the social structures of medieval European society.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('35cf8a54-1dba-4c0b-a16f-f1d0288b1cc5', 'ancient-history', 'Ancient', 'Games set in ancient civilizations -- Egypt, Rome, Greece, Mesopotamia, China, or other pre-medieval cultures. Pyramids, gladiators, philosophers, and bronze-age empires.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('63a17285-2485-47f3-aada-c719c70863d0', 'modern-era', 'Modern / Contemporary', 'Games set in the present day or recent history (post-1900). Contemporary settings, modern technology, and current-era concerns.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('21b16c4f-cd7a-4093-85b2-0075828270a8', 'wild-west', 'Wild West', 'Games set in the American frontier era (~1850-1900). Cowboys, outlaws, gold rushes, railroads, and frontier towns.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('9088e2a1-49ce-49c9-ab83-5f2eeeca2f7c', 'nautical', 'Nautical / Maritime', 'Games centered on oceans, sailing, naval warfare, or seafaring adventure. Ships, harbors, trade routes, and the open sea.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('d33a540d-db02-4994-965f-010f194c5c4a', 'urban', 'Urban / City', 'Games set in cities or focused on city building, metropolitan environments, and urban planning.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('0345ca05-83d0-4ab9-b52b-429cf0e540c9', 'war', 'War / Military Conflict', 'Games about armed conflict at any scale -- from squad-level tactics to global geopolitical warfare. Combat and military strategy are the central subject matter.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('8853d741-ba67-4a6e-992b-8dafd7de5d0d', 'horror', 'Horror', 'Games with dark, frightening, or supernatural themes designed to create tension, dread, or fear. Monsters, haunted locations, and survival against terrifying threats.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('4e0e9c9f-2f2a-4d20-b197-a65c2b804a84', 'lovecraftian', 'Lovecraftian / Cosmic Horror', 'Games featuring eldritch entities, sanity mechanics, forbidden knowledge, and the Cthulhu mythos or cosmic horror traditions. Specifically inspired by H.P. Lovecraft''s fiction.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('4bd8f3e3-07bf-4d9c-8c80-aec787130aa0', 'zombies', 'Zombies', 'Games about zombie outbreaks, survival against undead hordes, or post-apocalyptic worlds overrun by zombies.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('d4363a76-a4f7-4e09-90e2-4fc61018e513', 'mythology', 'Mythology', 'Games drawing on mythological traditions -- Greek, Norse, Egyptian, Celtic, Japanese, or other cultural mythologies. Gods, heroes, mythical creatures, and legendary narratives.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('bcb285ce-34f7-4c60-b07d-b8de53ca9523', 'pirates', 'Pirates', 'Games about piracy, treasure hunting, naval adventure on the high seas, and the romanticized pirate life.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('f0d3e32f-aaf4-4dcf-a452-ec1b9d287e5d', 'trains', 'Trains / Railroads', 'Games about rail networks, train operations, or railway investment. Building tracks, running trains, and managing railroad companies.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('51578c95-2ea7-4950-b09d-ba24d41b04e7', 'civilization', 'Civilization', 'Games about building, managing, and advancing entire societies across historical eras. Technology, culture, warfare, and diplomacy at civilization scale.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('f88b5866-ef08-462f-a384-71e0a4f1ffcf', 'nature', 'Nature / Wildlife', 'Games about animals, ecosystems, natural environments, and ecological themes. The natural world is the central subject.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('39168586-e109-4246-8d14-9effa9035a69', 'animals', 'Animals', 'Games where animals are the primary subject -- collecting, managing, or playing as animals. Distinct from nature/ecology by focusing on the creatures themselves.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('03a29879-5cca-4e57-a6cc-d190011c448a', 'farming', 'Farming / Agriculture', 'Games about farming, animal husbandry, harvesting crops, vineyard management, or agricultural life. Working the land as the central activity.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('a2639d72-c9ee-466b-9fb3-899d0d768c33', 'exploration', 'Exploration / Discovery', 'Games about discovering new lands, uncharted territory, or unknown environments. The thrill of revelation and the unknown.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('549fe8b6-ffe8-4729-8b38-d0b1aaf328a0', 'politics', 'Politics / Intrigue', 'Games about political maneuvering, governance, courtly intrigue, elections, or geopolitical strategy. Power through negotiation, manipulation, and influence rather than military force.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('42f89895-4224-4e45-ada4-58616ea5120f', 'espionage', 'Espionage', 'Games about spies, intelligence agencies, covert operations, and secret missions. Hidden information and deception in a spy thriller setting.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('cadd4ce7-4fcc-4147-8a6e-9464c8015c23', 'crime', 'Crime / Mystery', 'Games about criminal activity, detective work, investigation, or solving mysteries. Whodunits, heists, and forensic deduction.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('65b33668-bf3f-4a8c-92e9-37e211a0168c', 'trade', 'Trade / Commerce', 'Games about mercantile activity, shipping goods, establishing trade routes, and commercial exchange. Buying low, selling high, and building commercial empires.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('6a71de14-a1f9-43f4-9c9a-f06bb52b6b7a', 'industry', 'Industry / Manufacturing', 'Games about factories, production chains, industrial revolution, and manufacturing. Building industrial infrastructure and managing production output.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('25ad840b-f8f4-411b-bb90-e260a66b26b7', 'survival', 'Survival', 'Games about enduring harsh conditions, resource scarcity, and threats to survival. Staying alive is the primary challenge.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('17e04b9e-748e-40e9-9645-e93de449cb3e', 'adventure', 'Adventure', 'Games about questing, journeying, and exploration-driven narrative. The core experience is going on an adventure -- encounters, travel, and heroic challenges along the way.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('a2b48b8a-22c8-444b-a978-06c0ffdafcb0', 'comedy', 'Comedy / Humor', 'Games designed to be lighthearted, funny, and entertaining. Humor is a primary design goal, not incidental.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('c031425e-1eba-44ae-8b63-fb24800e1cba', 'steampunk', 'Steampunk', 'Games set in Victorian-era worlds with anachronistic technology -- steam-powered machines, clockwork devices, airships, and retro-futuristic aesthetics.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('27de57e1-d69f-4c11-99af-7607cace60db', 'superheroes', 'Superheroes', 'Games featuring comic-book heroes, superpowers, and the superhero genre conventions of secret identities, villains, and world-saving.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('ee543478-f6eb-435f-9422-81a3cb577d95', 'building', 'Building / Construction', 'Games about constructing structures, cities, monuments, or architectural works. The physical act of building something is the thematic focus.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('9d43d0a1-cfce-463e-9477-e9a00466d101', 'racing-theme', 'Racing', 'Games themed around competitive speed -- car racing, horse racing, sailing races, or any competition to reach a destination first.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('b086248b-f0ef-4bc7-a85b-860243808cbf', 'territory', 'Territory / Conquest', 'Games about claiming, defending, and expanding controlled territory. Maps, borders, and territorial dominance as the thematic focus.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('58dce064-9c51-43c3-9f15-28a72790b52d', 'medicine', 'Medicine / Science', 'Games with medical or scientific themes -- curing diseases, running hospitals, biological processes, or scientific research.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('02e31262-9c66-4e10-bba8-1ab5ea0e5e20', 'transportation', 'Transportation / Logistics', 'Games about moving goods or people, managing logistics networks, and transportation infrastructure beyond just trains.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('fac99f01-e9c5-451f-8c5f-7d865750bce7', 'empire', 'Empire / Nation-Building', 'Games about governing and expanding an empire or nation. Grand strategy at the national or imperial scale -- diplomacy, warfare, economy, and culture management.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('bac32485-e298-4e78-a98f-9fae92afb3d0', 'miniatures-theme', 'Miniatures', 'Games where miniature figures are central to the experience -- not just components but a core part of the hobby (painting, collecting, displaying). The miniatures hobby IS part of the game.', NULL);
INSERT INTO public.themes (id, slug, name, description, parent_id) VALUES ('d23b56cb-3652-40ca-9fbc-934ef1115ec9', 'abstract-theme', 'Abstract / Themeless', 'Games with no meaningful theme or where the theme is purely decorative. The game is about the mechanics and spatial/logical puzzles, not about simulating any subject matter.', NULL);
INSERT INTO public.game_themes (game_id, theme_id) VALUES ('01912f4c-7e3a-7b1a-8c5d-9f0e1a2b3c4d', 'b22b0236-7918-4db3-af35-baa91d965359');
